"""Final evidence-based curation and reviewer-risk reports; no computation reruns."""
from common import *
def main():
    c=verified_config();audit=read(P/'outputs/audits/INDEPENDENT_RESULT_AUDIT.json');facts=read(P/'outputs/experiment_tables/PAPER_NUMERIC_FACTS.json')
    assert audit['pass_']
    index=rd(P/'outputs/evidence_index/FIGURE_INDEX.csv');main_figs=['F02','F03','F04','F05','F06','F07','F11'];index['recommended_position']=np.where(index.id.isin(main_figs),'main','supplement')
    cs('outputs/evidence_index/FIGURE_INDEX.csv',index)
    src={'base_commit':BASE,'plot_script_sha256':sha(P/'scripts/plot_paper_figures.py'),'diagram_spec_sha256':sha(P/'outputs/experiment_tables/DIAGRAM_SPEC.json'),
         'note':'All12 original figures use new code and legal project CSV/spec. Published paper figures are reviewed but never copied.'}
    js('outputs/evidence_index/FIGURE_CODE_IDENTITY.json',src)
    text('reports/03_论文图表审查报告.md','# 论文图表审查与取舍\n\n'+mdtable(index[['id','recommended_position','source','caption']])+"\n\n正文建议控制为7个逻辑图位：F03任务、F02结构、F04公平比较、F05逐步/终点、F06历史工况、F07门控独立训练与推理证据、F11困难窗口。投稿排版可合并F02/F03，或将F11与预测实例合图。F01与任务/结构重复，移补充；F08是已选最佳实例，仅附带选择身份并与不利案例配对，不占据正式主性能结论。F09完整披露筛选；F10/F12作全Seed指标敏感性与重叠目标补充，必要时把其最关键表列进正文。\n\n不建议使用：竞争论文原图、把重复预测窗口拼成单次连续预测、只显示精选F2而隐藏正式Seed62、筛选六实例均值对比未筛F0/F1、以本文mV和不同论文的V/RUL误差直接排名。\n\n全部图为英文、统一语义配色与单位，300dpi PNG和同源PDF矢量输出。均值误差条是3Seed样本SD，逐步阴影是Seed最小—最大，不是CI。PSD/重复查询没有被解释成独立寿命样本。F08与F11各为单一origin完整24步，测量/预测电压均以原始起点V加ΔV一次。F02展示原LSTM hidden/cell直接进入decoder，融合encoder特征仅在与decoder表示concat后进入enrichment/attention；这是源码事实而不是新结构。图表文件尺寸、矢量路径及最终视觉审查结果见outputs/audits。\n")
    text('reports/04_论文创新性与审稿风险.md',"# 创新性与审稿风险\n\n本稿最稳妥的定位是“一个明确历史信息接口下的RealHyFC双路径TFT动态电压预测实证研究”，创新是实现与协议整合，强度有限。P1已有双路径卷积/条件预测，P2已有PEMFC TFT协变量，P3已有TCN-LSTM串联，P4已有TFT改进及原生对照；因此不能把这些通用名称当作首创。精确差异在共享VSN上的并行历史编码、post-LSTM encoder位置融合及冻结的direct48→24部署接口。原TFT本就区分known/unknown未来变量，该接口是本项目约束，不是理论首次。\n\n|风险|当前证据|必须怎样写|本轮解决程度|\n|---|---|---|---|\n|独立门控收益不足|P2 G2均值9.143434mV差于G0/G1的8.387048/8.349936；配对不一致|保留负面，门控为设计与诊断，不能宣称独立稳定增益|完整披露，科学缺口仍在|\n|验证选择偏差|Validation反复用于早停/方案反馈/两轮32次新尝试，精选6不是无偏样本|H正式3Seed作主比较，精选另列，全部预算与失败保留|分类与预算已整理，偏差不会消失|\n|独立性不足|I2是已复用Assessment；L否决当前Test确认资格|不称独立Test，不把未知历史影响写成已证实监督训练泄漏|只读保留资格，不能通过文稿修复|\n|基线池较窄|原生strict-history TFT、固定融合F1、动态F2和弱Persistence；旧N2不兼容|不直接拼LSTM/TCN旧成绩；缺同协议简单强基线|本轮只补无训练基线，真正缺口保留|\n|尾部和终点不稳|F2 Seed62 max307.984904mV、12h29.817395、目标等权27.053894|全点保留，显示排序反转及目标集中，不称全距离稳定|已完整复算和图示|\n|工况解释过度|三项是过去24h相对分位组，未来工况未知，窗口重叠|不说温湿压被控制，不做物理因果解释，不称9独立工况数据集|组定义及配对反例透明|\n|单数据、单耐久性堆|10cell组成一个耐久性实验，不是10独立寿命轨迹；另8cell BoL不同对象|只讨论本记录Development，不宣称跨堆/任意未来负载泛化|无法由新增文稿解决|\n\nSCI三区/四区只是目标层级，不能保证录用或免除上述问题。本轮未查询具体期刊最新分区，因未确定分区体系/年份，也不虚报任何期刊档次。按现有证据，最可能的审稿质疑是增量结构的新意、选后结果与反复验证、简单强基线不足、以及精度均值与极端/终点相矛盾。缩小贡献边界比增加未经验证的SOH/RUL/物理网络更合理。\n")
    text('reports/05_尚缺实验及最小补充计划.md',"# 真正影响投稿的缺口与最小后续方案\n\n本轮未训练任何模型，以下只是负责人审核用方案，不是自动执行清单。O1已做完的尾部/24步/目标等权不再列缺失；本轮Persistence与Train历史工况分析也已经完成。继续训练更多优秀F2种子不能填补独立性和结构归因缺口。\n\n如果只能补2～3项，按以下顺序考虑：\n\n1. **同协议简单强基线。** 最小可选为LSTM和TCN各3个预先固定、未经筛选的Seed，共6次训练；严格复用同1380/205窗口、同14槽/Top10/EWMA、Train-only scaler、同目标与评价规则，先冻结容量/训练预算/成功和停止条件。它解决模型池狭窄，而不是寻找新的backbone。旧N2三fold、233/245/466验证窗口及batch64/max300/pat30、per-horizon目标scaler不能直接复用。停止于固定预算，不因F2未胜出再调基线或换Seed。\n\n2. **真正合格的时间外评价。** 先核验访问历史、独立性、变量和采样兼容性，再冻结完整模型集合统一评价。当前仓库的既有暴露区域不能重新命名为未见Test；若没有新的未暴露、合法RealHyFC记录，这一项只能明确缺失，不能通过随意重切分或读取现有Test来补。是否取得新的合法记录由负责人决定，本轮没有获取数值或访问Test。它解决推广范围，而不是再改善已经反复使用的Validation。\n\n3. **部署型困难转换验证（有合格记录时）。** 在第2项成立后，按起点已知历史工况或预先给定负载计划冻结switch/恢复等评价规则，统一报告24步和终点/尾部。最小是复用全部既有冻结模型前向，无新主干。未来实测工况只能事后审计，不能作为未知未来预测输入；若没有起点已知计划及足够合法样本，则停止并不报在线泛化成绩。\n\n不把再次独立训练门控消融列优先项：P2已做9次、得到不一致/负面结果，应如实进入论文。若仍坚持独立门控增益主张，需要另行预注册且未经选择的对照预算，但当前更节省研究资源的选择是弱化该项主张。也不为借鉴参考论文而补SOH、RUL、PINN或物理损失。\n\n文献方面应补取得P3/P5全文，以完善其输入接口、跨度和消融细节；这属于文献资料缺口，不是开展新模型实验的理由。作者、基金、利益冲突与投稿格式等由负责人确认后补齐，不能由自动稿件推测。\n")
    # Preserve the calculation-before-drafting boundary while annotating actual completion.
    report=P/'reports/01_文献对标后论文结构调整说明.md'
    suffix='\n## 本轮计算实际完成状态\n\n大纲是计算前冻结的结构约束，其“待复算”描述对应设计时状态。现在预定输出均已真实生成并独立核验：九正式模型+Persistence共49200查询，90个历史分组设置，800项标量核验最大差异'+str(audit['max_difference'])+'。状态见outputs/audits/COMPUTATION_STATUS.json及INDEPENDENT_RESULT_AUDIT.json；没有新训练、模型前向或Test访问。大纲原始SHA保持，不以事后结果调整其结构或分组规则。\n'
    base=report.read_text(encoding='utf-8').split('\n## 本轮计算实际完成状态')[0];text(str(report.relative_to(P)),base+suffix)
    print('CURATED_FIGURES_AND_REVIEWER_RISK_REPORTS_COMPLETE')
if __name__=='__main__':main()
